import math

def calculate_pretty(m, n, alpha):
    """Calculates m*ceil(n*alpha) - n*floor(m*alpha)"""
    try:
        # Ensure alpha is treated as a float for math functions
        if not isinstance(alpha, (float, int)):
             alpha = float(alpha)

        term1 = m * math.ceil(n * alpha)
        term2 = n * math.floor(m * alpha)
        return term1 - term2
    except OverflowError:
        return None

# Test cases: m+n <= 10
test_pairs = []
for m in range(1, 10):
    for n in range(1, 10):
        if m + n <= 10:
            test_pairs.append((m, n))

# Irrational values of alpha to test
alphas = [math.sqrt(2), math.pi, math.e]

results = {}

print("--- Testing Pretty Condition for Small (m, n) ---")
for m, n in test_pairs:
    results[(m, n)] = {}
    for alpha in alphas:
        result = calculate_pretty(m, n, alpha)
        results[(m, n)][alpha] = result
        print(f"(m={m}, n={n}) with alpha={alpha:.4f}: Result = {result}")

# Print summary for easy reading
print("\n--- Summary of Results ---")
for (m, n), results_dict in results.items():
    values = list(results_dict.values())
    if all(abs(v - values[0]) < 1e-9 for v in values):
        print(f"Pair ({m}, {n}) is CONSTANT: Value = {values[0]}")
    else:
        print(f"Pair ({m}, {n}) is VARIABLE: Values = {values}")
